//! P4a executable service-routing capability matrix for issue #10.
//!
//! Classification only: every maintained C-Gate command path (the 224
//! public-manual headings in `manual::DOCUMENTED_COMMANDS` plus the 268
//! bytecode registrations in `manual::DECOMPILED_COMMAND_GROUPS`, 431 unique
//! paths) classified by how cmqttd's physical service endpoint routes it.
//! The endpoint includes `service::Service::handle` plus the TCP/TLS
//! connection state that owns EVENT subscriptions, session identity and QUIT.
//!
//! Routing classes (read against endpoint dispatch order, then
//! `service::local_command`):
//!
//! - `Physical`: a dedicated pre-gate branch in `Service::handle` serves a
//!   well-formed invocation (PCI bus I/O, or bus-observed state such as the
//!   pre-gate GET|GETSTATE level read). Transport failures surface from the
//!   driver, not from the fail-closed gate.
//! - `LocalDatabase`: no pre-gate branch matches, and `local_command()`
//!   admits a well-formed invocation to the durable in-memory model with no
//!   bus I/O (database verbs, admitted PROJECT/PP subcommands, 3-word GET,
//!   NOOP/APIVER/HELP).
//! - `FailClosed502`: a well-formed invocation is refused with 502 and no bus
//!   I/O, either by an explicit fail-closed branch (`DO UNRAVEL`) or by the
//!   generic `local_command() == false` gate. Paths whose readings span
//!   classes with no clear primary (notably `DO`: physical methods, 502 for
//!   UNRAVEL, 402/400 for method and arity gating) are classified
//!   conservatively here, with the fan-out recorded in evidence.
//! - `Obsolete400`: native-declared obsolete, deterministic 400 with no
//!   physical I/O (`NET CHECK_UNRAVEL` only).
//! - `Rejected4xx`: reserved for paths deterministically rejected with 4xx
//!   without bus I/O. No inventoried path is purely in this class today:
//!   arity-gated 4xx readings (short `DO` to 400, unknown `DO` methods to
//!   402) share their path with physical and fail-closed readings and are
//!   therefore covered conservatively under `FailClosed502` (see the `DO`
//!   row). The conformance test pins this membership so drift is caught.
//!   `Rejected4xx` being empty is expected and pinned, not an omission.
//!
//! Inventory-relative bound: the 431 rows below cover exactly the manual
//! inventory universe (`manual::DOCUMENTED_COMMANDS` plus
//! `manual::DECOMPILED_COMMAND_GROUPS`), pinned by
//! `tests/capability_matrix.rs`. Service commands outside that universe
//! are not inventoried here; the known non-inventoried commands are
//! listed explicitly in `SUPPLEMENT_ROUTING` (CMQTT CAPABILITIES, CMQTT
//! LABELS, UNIT READMEM, UNIT IDENTIFY, TRIGGER INDICATORKILL, LIGHTING
//! STOP) with their routing classes asserted separately in-test. This
//! file builds no second inventory.
//!
//! Primary-reading convention: an inventoried path whose readings span
//! classes keeps one row in the class of its primary (bus-control)
//! reading, with the split documented in the evidence string (SCENE:
//! PLAY physical / RECORD local; CLOCK DATE|TIME: 4-word physical /
//! 3-word local; PP LOAD|SAVE: non-/db/ physical, /db/-scoped local).
//! Note the /db/ case asymmetry: `Service::handle` matches the /db/
//! prefix case-insensitively while `local_command()` admits it
//! case-sensitively, so mixed-case sources fall through to the 502 gate.

/// How cmqttd's physical service routes one inventoried command path.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum RoutingClass {
    /// Dedicated pre-gate branch in `Service::handle` (bus I/O or bus-observed state).
    Physical,
    /// Served from the in-memory model or command-connection state, with no
    /// physical bus I/O. The stable wire name predates session commands.
    LocalDatabase,
    /// Explicit or generic-gate 502 with no bus I/O (conservative home for ambiguous paths).
    FailClosed502,
    /// Native-declared obsolete, deterministic 400.
    Obsolete400,
    /// Deterministic 4xx without bus I/O (currently unoccupied; pinned by test).
    Rejected4xx,
}

impl RoutingClass {
    /// Stable wire name for the class.
    pub fn as_str(self) -> &'static str {
        match self {
            RoutingClass::Physical => "physical",
            RoutingClass::LocalDatabase => "local_database",
            RoutingClass::FailClosed502 => "fail_closed_502",
            RoutingClass::Obsolete400 => "obsolete_400",
            RoutingClass::Rejected4xx => "rejected_4xx",
        }
    }
}

/// One inventoried command path and how the physical service routes it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CapabilityEntry {
    /// Inventoried command path, e.g. `NET UNRAVEL`.
    pub path: &'static str,
    /// How the physical service endpoint routes a well-formed invocation.
    pub class: RoutingClass,
    /// Handler or test reference showing the work (branch or gate).
    pub evidence: &'static str,
}

